// Intended function: preflight all inventory deltas before committing any line so cross-system transfers never partially delete or duplicate matter.
#include "gameplay/InventoryTransactions.hpp"
namespace elysium{bool InventoryTransactionLedger::prepare(InventoryTransaction t){if(!t.transactionId||t.lines.empty()||transactions_.contains(t.transactionId))return false;transactions_[t.transactionId]=std::move(t);return true;}bool InventoryTransactionLedger::commit(std::uint64_t id,std::unordered_map<std::uint64_t,std::unordered_map<std::uint32_t,std::uint32_t>>&inv){auto i=transactions_.find(id);if(i==transactions_.end()||i->second.state!=InventoryTransactionState::Prepared)return false;for(auto&l:i->second.lines)if(l.quantityDelta<0&&std::int64_t(inv[l.ownerId][l.itemId])+l.quantityDelta<0){i->second.state=InventoryTransactionState::Rejected;return false;}for(auto&l:i->second.lines){auto&v=inv[l.ownerId][l.itemId];v=std::uint32_t(std::int64_t(v)+l.quantityDelta);}i->second.state=InventoryTransactionState::Committed;return true;}bool InventoryTransactionLedger::rollback(std::uint64_t id){auto i=transactions_.find(id);if(i==transactions_.end()||i->second.state!=InventoryTransactionState::Prepared)return false;i->second.state=InventoryTransactionState::RolledBack;return true;}const InventoryTransaction*InventoryTransactionLedger::find(std::uint64_t id)const{auto i=transactions_.find(id);return i==transactions_.end()?nullptr:&i->second;}}
